def main():
    phase = sys.argv[1]
    claims = io.open(CLAIMS, encoding="utf-8", newline="").read()
    assert "\r\n" in claims
    block = io.open(BLOCK, encoding="utf-8").read() if BLOCK.exists() else ""
    add_c, add_b = [], []
    if HEADER not in claims:
        add_c.append(HEADER); add_c.append("")
    if HEADER not in block:
        add_b.append(HEADER); add_b.append("")
    for e in ENTRIES[phase]:
        key = e.split("]**")[0]
        if key not in claims:
            add_c.append(e)
        if key not in block:
            add_b.append(e)
    if add_c:
        if not claims.endswith("\r\n"):
            claims += "\r\n"
        claims += "\r\n".join(add_c) + "\r\n"
        io.open(CLAIMS, "w", encoding="utf-8", newline="").write(claims)
    if add_b:
        if block and not block.endswith("\n"):
            block += "\n"
        block += "\n".join(add_b) + "\n"
        io.open(BLOCK, "w", encoding="utf-8", newline="\n").write(block)
    print(f"land_r123 {phase}: {len(add_c)} lines appended to CLAIMS.md, {len(add_b)} to claims_r123_block.md")


if __name__ == "__main__":
    main()
